        active: hasActiveDispatchedRun(repoInfo, ciWorkflow, headSha),
        verdict: latestDispatchedVerdict(repoInfo, ciWorkflow, headSha),
        green: hasSuccessfulDispatchedRun(repoInfo, ciWorkflow, headSha),
